import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as e,e as s}from"./app-09e0be14.js";const i={},d=s(`<h1 id="ninja-小型高速构建系统-常与-cmake-配合使用" tabindex="-1"><a class="header-anchor" href="#ninja-小型高速构建系统-常与-cmake-配合使用" aria-hidden="true">#</a> ninja（小型高速构建系统，常与 CMake 配合使用）</h1><blockquote><p>Homebrew 版本 1.13.2 ｜ 主页：见官方文档 ｜ 安装：<code>brew install ninja</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>ninja 是一个专注于<strong>速度</strong>的小型构建系统，它的设计目标是在大规模项目的增量构建中做到极快。它不像 Make 那样内置复杂的构建逻辑，而是依赖上层工具（最常见的是 CMake）先生成描述文件，再由 ninja 快速执行，从而在几百上千个源文件的工程里实现近乎线性的构建时间。</p><p>典型应用场景：配合 CMake 生成 ninja 构建文件后编译大型 C/C++ 工程（如 Chromium、LLVM 都基于它），或在 CI 流水线中追求更快的编译反馈。它的定位是&quot;底层执行引擎&quot;，而不是&quot;完整构建框架&quot;。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>通过 Homebrew 安装、升级、卸载，以及验证：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> ninja

<span class="token comment"># 升级到最新版</span>
brew upgrade ninja

<span class="token comment"># 卸载</span>
brew uninstall ninja

<span class="token comment"># 验证安装成功（应输出类似 ninja version 1.13.2）</span>
ninja <span class="token parameter variable">--version</span>

<span class="token comment"># 查看帮助</span>
ninja <span class="token parameter variable">-h</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果提示 <code>command not found</code>，先确认 <code>/opt/homebrew/bin</code>（Apple Silicon）或 <code>/usr/local/bin</code>（Intel）已在 PATH 中。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>ninja</code></td><td>无参数时按默认目标构建</td><td><code>ninja</code></td></tr><tr><td><code>ninja &lt;target&gt;</code></td><td>只构建指定目标</td><td><code>ninja ninjatool</code></td></tr><tr><td><code>ninja -C &lt;dir&gt;</code></td><td>先切换到指定目录再执行构建</td><td><code>ninja -C build</code></td></tr><tr><td><code>ninja -j N</code></td><td>指定并行任务数，默认按 CPU 核心数</td><td><code>ninja -j 8</code></td></tr><tr><td><code>ninja -t targets</code></td><td>列出所有可用的构建目标</td><td><code>ninja -t targets</code></td></tr><tr><td><code>ninja -t clean</code></td><td>清理构建产物</td><td><code>ninja -t clean</code></td></tr><tr><td><code>ninja -t commands</code></td><td>显示将执行的构建命令（不执行）</td><td><code>ninja -t commands all</code></td></tr><tr><td><code>ninja -n</code></td><td>预演（dry run），只打印命令不执行</td><td><code>ninja -n</code></td></tr><tr><td><code>ninja -v</code></td><td>显示执行的详细命令行</td><td><code>ninja -v</code></td></tr><tr><td><code>ninja -t graph</code></td><td>以 Graphviz DOT 格式输出依赖图</td><td><code>ninja -t graph &gt; graph.dot</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-与-cmake-配合编译一个-c-工程" tabindex="-1"><a class="header-anchor" href="#示例-1-与-cmake-配合编译一个-c-工程" aria-hidden="true">#</a> 示例 1：与 CMake 配合编译一个 C++ 工程</h3><p>最典型的用法：CMake 生成 ninja 构建文件，再用 ninja 编译。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 准备一个简单的 C++ 工程</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> demo <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> demo
<span class="token function">cat</span> <span class="token operator">&gt;</span> hello.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;iostream&gt;
int main() {
    std::cout &lt;&lt; &quot;Hello, ninja!&quot; &lt;&lt; std::endl;
    return 0;
}
EOF</span>

<span class="token comment"># 2. 用 CMake 生成 ninja 构建文件（进入 build 目录，避免污染源码树）</span>
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-G</span> Ninja

<span class="token comment"># 3. 执行构建</span>
cmake <span class="token parameter variable">--build</span> build

<span class="token comment"># 4. 运行生成的可执行文件</span>
./build/hello
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出应包含 <code>Hello, ninja!</code>。也可直接 <code>ninja -C build</code> 代替第 3 步。</p><h3 id="示例-2-增量构建验证-ninja-的速度" tabindex="-1"><a class="header-anchor" href="#示例-2-增量构建验证-ninja-的速度" aria-hidden="true">#</a> 示例 2：增量构建验证 ninja 的速度</h3><p>在示例 1 的工程上测试增量编译：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 修改源码后重新构建，ninja 只重编受影响的文件</span>
<span class="token builtin class-name">echo</span> <span class="token string">&#39;// just a comment to trigger rebuild&#39;</span> <span class="token operator">&gt;&gt;</span> hello.cpp
<span class="token function">time</span> ninja <span class="token parameter variable">-C</span> build

<span class="token comment"># 不做任何修改再次构建，应几乎瞬间完成</span>
<span class="token function">time</span> ninja <span class="token parameter variable">-C</span> build
<span class="token comment"># 第二次输出：ninja: no work to do.</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>第二次构建会因为无改动而立即结束，体现 ninja 的增量构建优势。</p><h3 id="示例-3-直接手写-build-ninja-不依赖-cmake" tabindex="-1"><a class="header-anchor" href="#示例-3-直接手写-build-ninja-不依赖-cmake" aria-hidden="true">#</a> 示例 3：直接手写 build.ninja（不依赖 CMake）</h3><p>ninja 也可以脱离 CMake 单独使用，手动编写构建文件：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 准备源文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> main.c <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;stdio.h&gt;
int main(void) { printf(&quot;direct ninja\\n&quot;); return 0; }
EOF</span>

<span class="token comment"># 2. 手写最小 build.ninja</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> build.ninja <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
rule cc
  command = cc -c $in -o $out
rule link
  command = cc $in -o $out

build main.o: cc main.c
build app: link main.o
default app
EOF</span>

<span class="token comment"># 3. 执行</span>
ninja

<span class="token comment"># 4. 运行</span>
./app
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出为 <code>direct ninja</code>。此例展示了 ninja 的 <code>rule</code>（规则）与 <code>build</code>（构建语句）语法。</p><h3 id="示例-4-生成依赖图辅助调试" tabindex="-1"><a class="header-anchor" href="#示例-4-生成依赖图辅助调试" aria-hidden="true">#</a> 示例 4：生成依赖图辅助调试</h3><p>对已有构建文件输出依赖关系图：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 在示例 1 的 build 目录中</span>
ninja <span class="token parameter variable">-C</span> build <span class="token parameter variable">-t</span> graph <span class="token operator">&gt;</span> graph.dot

<span class="token comment"># 若安装了 graphviz，可渲染成图片</span>
dot <span class="token parameter variable">-Tpng</span> graph.dot <span class="token parameter variable">-o</span> graph.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-让-cmake-默认使用-ninja" tabindex="-1"><a class="header-anchor" href="#_1-让-cmake-默认使用-ninja" aria-hidden="true">#</a> 1. 让 CMake 默认使用 Ninja</h3><p>若希望 <code>cmake ..</code> 时不写 <code>-G Ninja</code>，可在 <code>CMakePresets.json</code> 中指定生成器，或设置环境变量：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">CMAKE_GENERATOR</span><span class="token operator">=</span>Ninja
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>此后直接 <code>cmake -S . -B build</code> 即用 ninja 构建。</p><h3 id="_2-配置并行度与-ninja-自身的常量" tabindex="-1"><a class="header-anchor" href="#_2-配置并行度与-ninja-自身的常量" aria-hidden="true">#</a> 2. 配置并行度与 Ninja 自身的常量</h3><p><code>-j</code> 可手动控制并行度；ninja 读取 <code>NINJA_STATUS</code> 环境变量自定义状态行格式：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">NINJA_STATUS</span><span class="token operator">=</span><span class="token string">&quot;[%f/%t] &quot;</span>
ninja <span class="token parameter variable">-j</span> <span class="token number">4</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>常见占位符：<code>%f</code>（完成数）、<code>%t</code>（总数）、<code>%p</code>（百分比）、<code>%s</code>（已运行秒数）、<code>%e</code>（预计剩余秒数）。</p><h3 id="_3-用-t-compdb-导出-compile-commands-json" tabindex="-1"><a class="header-anchor" href="#_3-用-t-compdb-导出-compile-commands-json" aria-hidden="true">#</a> 3. 用 <code>-t compdb</code> 导出 compile_commands.json</h3><p>需要给 IDE/代码补全工具（如 clangd）提供编译数据库时：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>ninja <span class="token parameter variable">-C</span> build <span class="token parameter variable">-t</span> compdb cxx <span class="token operator">&gt;</span> compile_commands.json
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_4-结合-ccache-加速重复编译" tabindex="-1"><a class="header-anchor" href="#_4-结合-ccache-加速重复编译" aria-hidden="true">#</a> 4. 结合 ccache 加速重复编译</h3><p>把 ninja 与 ccache 搭配，能显著缓存重复的编译结果：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># CMake 中启用</span>
cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-G</span> Ninja <span class="token parameter variable">-DCMAKE_CXX_COMPILER_LAUNCHER</span><span class="token operator">=</span>ccache
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-手写-build-ninja-的核心语法" tabindex="-1"><a class="header-anchor" href="#_5-手写-build-ninja-的核心语法" aria-hidden="true">#</a> 5. 手写 build.ninja 的核心语法</h3><p>ninja 的构建文件由三类核心元素组成：<strong>变量（variable）、规则（rule）、构建语句（build）</strong>。</p><p><strong>变量</strong>使用 <code>名称 = 值</code> 定义，在 <code>$名称</code> 处引用；<code>$in</code>、<code>$out</code> 是 ninja 预置的隐式变量，分别代表规则的输入与输出列表：</p><div class="language-ninja line-numbers-mode" data-ext="ninja"><pre class="language-ninja"><code># 顶层变量，可在 rule / build 中引用
cc = cc
cflags = -Wall -O2

rule cc
  command = $cc -c $cflags $in -o $out   # $in 和 $out 自动展开
  description = CC $out                  # 构建时显示的可读信息
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>**rule（规则）**描述&quot;如何把输入变成输出&quot;，即一条可复用的命令模板。<code>command</code> 是必填项，其余如 <code>depfile</code>、<code>description</code>、<code>rspfile</code>、<code>generator</code> 为可选属性。</p><p><strong>build 语句</strong>把&quot;输入 → 输出&quot;与某条 rule 关联起来，并声明隐式依赖：</p><div class="language-ninja line-numbers-mode" data-ext="ninja"><pre class="language-ninja"><code># 语法：build &lt;输出&gt;: &lt;rule&gt; &lt;输入...&gt;
build main.o: cc main.c
build app: link main.o | deps.ld         # | 后是隐式依赖（仅参与依赖判断，不进入 $in）
build app: link main.o || gen_headers    # || 后是 order-only 依赖（先构建但不触发重建）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong><code>default</code> 语句</strong>声明默认构建目标；缺省时 ninja 构建文件中出现的所有 build 输出：</p><div class="language-ninja line-numbers-mode" data-ext="ninja"><pre class="language-ninja"><code>default app
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_6-通过-depfile-让头文件依赖生效" tabindex="-1"><a class="header-anchor" href="#_6-通过-depfile-让头文件依赖生效" aria-hidden="true">#</a> 6. 通过 <code>depfile</code> 让头文件依赖生效</h3><p>手写 build.ninja 时最易忽略的是<strong>头文件依赖</strong>。若编译器修改了某个头文件，而构建文件未声明该依赖，ninja 不会重编相关源文件。正确做法是让编译器输出依赖文件，再用 <code>depfile</code> 让 ninja 读取：</p><div class="language-ninja line-numbers-mode" data-ext="ninja"><pre class="language-ninja"><code>rule cc
  command = cc -MD -MF $out.d -c $in -o $out   # -MF 指定依赖文件输出路径
  depfile = $out.d                             # 告诉 ninja 读取此依赖文件
  deps = gcc                                   # 依赖文件的语法类型（gcc / msvc）

build main.o: cc main.c
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>-MD</code> 让 GCC/Clang 自动生成依赖文件，ninja 解析后即可精确跟踪 <code>#include</code> 的头文件，增量构建才真正可靠。</p><h3 id="_7-用-rspfile-处理超长命令行" tabindex="-1"><a class="header-anchor" href="#_7-用-rspfile-处理超长命令行" aria-hidden="true">#</a> 7. 用 <code>rspfile</code> 处理超长命令行</h3><p>命令行过长会触发 ARG_MAX 限制。ninja 支持把参数写入响应文件（response file），再通过 <code>@</code> 传给编译器：</p><div class="language-ninja line-numbers-mode" data-ext="ninja"><pre class="language-ninja"><code>rule link
  command = ld @$out.rsp -o $out
  rspfile = $out.rsp          # 响应文件路径
  rspfile_content = $in       # 写入响应文件的内容

build app: link main.o foo.o bar.o
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适合链接几百个目标文件的大工程，避免命令行超限。</p><h3 id="_8-配合-cmake-输出依赖图与诊断" tabindex="-1"><a class="header-anchor" href="#_8-配合-cmake-输出依赖图与诊断" aria-hidden="true">#</a> 8. 配合 CMake 输出依赖图与诊断</h3><p>对 CMake 生成的大型 build.ninja，可用 <code>-t</code> 系列工具快速定位问题（详见下文诊断工具一节）。</p><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-不要直接手工维护-build-ninja" tabindex="-1"><a class="header-anchor" href="#_1-不要直接手工维护-build-ninja" aria-hidden="true">#</a> 1. 不要直接手工维护 build.ninja</h3><p>对真实项目，build.ninja 应由 CMake 等工具生成。手动编辑后下次 CMake 重新生成会被覆盖，且手写语法容易出错。只在学习或极小场景下才手写。</p><h3 id="_2-报错-unknown-target" tabindex="-1"><a class="header-anchor" href="#_2-报错-unknown-target" aria-hidden="true">#</a> 2. 报错 &quot;unknown target&quot;</h3><p><code>ninja: unknown target &#39;xxx&#39;</code> 表示目标名写错。先用 <code>ninja -t targets</code> 查看可用目标，确认拼写。</p><h3 id="_3-报错-build-ninja-is-missing" tabindex="-1"><a class="header-anchor" href="#_3-报错-build-ninja-is-missing" aria-hidden="true">#</a> 3. 报错 &quot;build.ninja is missing&quot;</h3><p>在项目根目录直接运行 <code>ninja</code> 而该目录下没有 <code>build.ninja</code>。使用 <code>-C</code> 指定生成目录，或先运行 CMake 生成。</p><h3 id="_4-并行任务过多导致内存-编译报错" tabindex="-1"><a class="header-anchor" href="#_4-并行任务过多导致内存-编译报错" aria-hidden="true">#</a> 4. 并行任务过多导致内存/编译报错</h3><p><code>-j</code> 默认等于 CPU 核心数，在内存较小的机器上可能 OOM 或编译器崩溃。可降低并行度：<code>ninja -j 2</code>。</p><h3 id="_5-换编译器后需重新生成" tabindex="-1"><a class="header-anchor" href="#_5-换编译器后需重新生成" aria-hidden="true">#</a> 5. 换编译器后需重新生成</h3><p>仅修改环境变量编译器不一定生效，ninja 缓存了旧的编译命令。修改后应删除 build 目录重新 <code>cmake -S . -B build -G Ninja</code>，避免使用过期命令。</p><h3 id="_6-性能提示" tabindex="-1"><a class="header-anchor" href="#_6-性能提示" aria-hidden="true">#</a> 6. 性能提示</h3><p>ninja 本身开销极低，但若 build.ninja 由 CMake 生成，<code>cmake</code> 重新配置本身会耗时。把源码与构建目录分开（out-of-source）可减少触发重新配置的干扰文件，保持 ninja 的高效增量构建。</p><h3 id="_7-头文件依赖未声明导致漏编" tabindex="-1"><a class="header-anchor" href="#_7-头文件依赖未声明导致漏编" aria-hidden="true">#</a> 7. 头文件依赖未声明导致漏编</h3><p>手工 build.ninja 中最常见的坑。若没有 <code>depfile</code>/<code>deps</code>，修改 <code>.h</code> 不会触发相关 <code>.o</code> 重编，产出一致性无法保证。始终为编译规则配置依赖文件（见五-6）。</p><h3 id="_8-只改一个文件却全量重编" tabindex="-1"><a class="header-anchor" href="#_8-只改一个文件却全量重编" aria-hidden="true">#</a> 8. 只改一个文件却全量重编</h3><p>若某目标把多个源文件塞进一条 build 命令（如一次编译所有 <code>.c</code>），任何一个变化都会重跑整条命令。应为每个源文件建独立 <code>build x.o: cc x.c</code> 语句，让 ninja 能按文件粒度增量。</p><h3 id="_9-构建目录有残留导致的-幽灵失败" tabindex="-1"><a class="header-anchor" href="#_9-构建目录有残留导致的-幽灵失败" aria-hidden="true">#</a> 9. 构建目录有残留导致的&quot;幽灵失败&quot;</h3><p>修改了 CMakeLists 却忘记重新配置，或构建目录里残留旧的中间文件，可能产生难以定位的错误。养成定期 <code>ninja -t clean</code> 或直接删除 build 目录重建的习惯。</p><h3 id="_10-cleandead-清理失效的旧产物" tabindex="-1"><a class="header-anchor" href="#_10-cleandead-清理失效的旧产物" aria-hidden="true">#</a> 10. <code>cleandead</code> 清理失效的旧产物</h3><p>若从构建脚本中删除了某些目标（如 CMake 里移除了某源文件），<code>ninja -t clean</code> 默认不清掉这些已不再受管的旧产物。用 <code>cleandead</code> 删除 build 图之外的失效文件：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>ninja <span class="token parameter variable">-t</span> cleandead
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>注意：它会删除不受任何目标管理但仍在构建目录中的文件，使用前确认没有需要保留的生成物。</p><h3 id="_11-默认构建目标不包含你要的东西" tabindex="-1"><a class="header-anchor" href="#_11-默认构建目标不包含你要的东西" aria-hidden="true">#</a> 11. 默认构建目标不包含你要的东西</h3><p><code>ninja</code> 只构建 <code>default</code> 声明的目标。CMake 生成的默认目标通常是 <code>all</code>；若只想编某个库/可执行文件，显式指定：<code>ninja &lt;target&gt;</code>，或先 <code>ninja -t targets</code> 确认目标名。</p><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-与-cmake-配合-g-ninja-与-ninja-multi-config" tabindex="-1"><a class="header-anchor" href="#_1-与-cmake-配合-g-ninja-与-ninja-multi-config" aria-hidden="true">#</a> 1. 与 CMake 配合：<code>-G Ninja</code> 与 Ninja Multi-Config</h3><p><strong>单配置</strong>：<code>cmake -S . -B build -G Ninja</code> 生成单一配置（如 Debug 或 Release，由 <code>-DCMAKE_BUILD_TYPE</code> 决定）。</p><p><strong>多配置</strong>：使用 <code>Ninja Multi-Config</code> 生成器，可在同一构建目录内存放多个配置，切换无需重新生成：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-G</span> <span class="token string">&quot;Ninja Multi-Config&quot;</span> <span class="token parameter variable">-DCMAKE_CONFIGURATION_TYPES</span><span class="token operator">=</span><span class="token string">&quot;Debug;Release&quot;</span>

<span class="token comment"># 构建指定配置</span>
ninja <span class="token parameter variable">-C</span> build <span class="token parameter variable">-f</span> build-Debug.ninja        <span class="token comment"># 生成器会为每个配置生成独立 ninja 文件</span>
<span class="token comment"># 或通过 CMake 语法</span>
cmake <span class="token parameter variable">--build</span> build <span class="token parameter variable">--config</span> Debug
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>实际使用中更推荐通过 <code>CMakePresets.json</code> 定义不同配置的 preset，一键切换：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token number">6</span><span class="token punctuation">,</span>
  <span class="token property">&quot;configurePresets&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;ninja-debug&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;generator&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Ninja&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;binaryDir&quot;</span><span class="token operator">:</span> <span class="token string">&quot;build/debug&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;cacheVariables&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;CMAKE_BUILD_TYPE&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Debug&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;ninja-release&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;generator&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Ninja&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;binaryDir&quot;</span><span class="token operator">:</span> <span class="token string">&quot;build/release&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;cacheVariables&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;CMAKE_BUILD_TYPE&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Release&quot;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span>
  <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">--preset</span> ninja-debug <span class="token operator">&amp;&amp;</span> cmake <span class="token parameter variable">--build</span> <span class="token parameter variable">--preset</span> ninja-debug
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_2-与-meson-配合" tabindex="-1"><a class="header-anchor" href="#_2-与-meson-配合" aria-hidden="true">#</a> 2. 与 meson 配合</h3><p>meson 本身就是 ninja 的忠实用户，默认生成 build.ninja。你几乎看不到 meson 手写 ninja 文件，只需关注 meson 自身命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>meson setup build
ninja <span class="token parameter variable">-C</span> build          <span class="token comment"># meson 生成的 build 目录就是 ninja 可用的目录</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>meson 生成的 <code>build.ninja</code> 中蕴含了完整的依赖与安装逻辑，直接 <code>ninja -C build</code> 即可增量编译，也能用 <code>ninja -t compdb c</code> 导出编译数据库。</p><h3 id="_3-用自定义-build-ninja-构建一个小型-c-工程" tabindex="-1"><a class="header-anchor" href="#_3-用自定义-build-ninja-构建一个小型-c-工程" aria-hidden="true">#</a> 3. 用自定义 build.ninja 构建一个小型 C 工程</h3><p>综合前面语法，构建一个多文件小型 C 工程（含头文件依赖与默认目标）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备源码</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> myproj <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> myproj
<span class="token function">cat</span> <span class="token operator">&gt;</span> math.c <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &quot;math.h&quot;
int add(int a, int b) { return a + b; }
EOF</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> main.c <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;stdio.h&gt;
#include &quot;math.h&quot;
int main(void) { printf(&quot;%d\\n&quot;, add(2, 3)); return 0; }
EOF</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> math.h <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
int add(int, int);
EOF</span>

<span class="token comment"># 手写 build.ninja，使用 depfile 跟踪头文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> build.ninja <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
cc = cc

rule cc
  command = $cc -MD -MF $out.d -c $in -o $out
  depfile = $out.d
  deps = gcc
rule link
  command = $cc $in -o $out

build math.o: cc math.c
build main.o: cc main.c
build app: link main.o math.o
default app
EOF</span>

ninja <span class="token operator">&amp;&amp;</span> ./app    <span class="token comment"># 输出 5</span>
<span class="token builtin class-name">echo</span> <span class="token string">&#39;#define ADD_V2 1&#39;</span> <span class="token operator">&gt;&gt;</span> math.h   <span class="token comment"># 修改头文件</span>
ninja             <span class="token comment"># 只重编依赖 math.h 的 math.o、main.o，而非全量</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-在-ci-中加速构建" tabindex="-1"><a class="header-anchor" href="#_4-在-ci-中加速构建" aria-hidden="true">#</a> 4. 在 CI 中加速构建</h3><p>CI（如 GitHub Actions、GitLab CI）里用 ninja 提升反馈速度：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/build.yml（节选）</span>
<span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build
  <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
    cmake -S . -B build -G Ninja -DCMAKE_BUILD_TYPE=Release
    cmake --build build -j $(nproc)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：<code>-j</code> 按机器核心数设置并行度；若 CI 缓存依赖（如 ccache），把构建目录纳入缓存以复用增量结果；对纯 ninja 项目直接 <code>ninja -C build</code>。</p><h3 id="_5-性能优化-用-t-诊断工具定位瓶颈" tabindex="-1"><a class="header-anchor" href="#_5-性能优化-用-t-诊断工具定位瓶颈" aria-hidden="true">#</a> 5. 性能优化：用 <code>-t</code> 诊断工具定位瓶颈</h3><p>ninja 内置的 <code>-t</code> 工具是排查构建问题、理解构建图的利器：</p><table><thead><tr><th>子命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>targets</code></td><td>列出目标及规则</td><td><code>ninja -t targets all</code></td></tr><tr><td><code>commands</code></td><td>打印各目标的执行命令</td><td><code>ninja -t commands all</code></td></tr><tr><td><code>query &lt;目标&gt;</code></td><td>查看某目标输入/输出/依赖详情</td><td><code>ninja -t query app</code></td></tr><tr><td><code>graph</code></td><td>输出 DOT 依赖图</td><td><code>ninja -t graph &gt; g.dot</code></td></tr><tr><td><code>compdb</code></td><td>导出编译数据库</td><td><code>ninja -t compdb cxx</code></td></tr><tr><td><code>deps</code></td><td>查看目标的依赖文件列表</td><td><code>ninja -t deps</code></td></tr><tr><td><code>clean</code> / <code>cleandead</code></td><td>清理构建产物 / 失效产物</td><td><code>ninja -t clean</code></td></tr><tr><td><code>restat</code></td><td>调试 <code>restat</code> 相关时序（高级）</td><td><code>ninja -t restat</code></td></tr></tbody></table><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看 app 由哪些文件构建而来，及其依赖</span>
ninja <span class="token parameter variable">-C</span> build <span class="token parameter variable">-t</span> query app

<span class="token comment"># 只打印编译 main.o 的命令</span>
ninja <span class="token parameter variable">-C</span> build <span class="token parameter variable">-t</span> commands main.o
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-理解增量构建原理-ninja-log-与-ninja-deps" tabindex="-1"><a class="header-anchor" href="#_6-理解增量构建原理-ninja-log-与-ninja-deps" aria-hidden="true">#</a> 6. 理解增量构建原理：.ninja_log 与 .ninja_deps</h3><p>ninja 的极速增量依赖两个隐藏文件，位于构建目录根：</p><ul><li><strong><code>.ninja_log</code></strong>：记录每次执行过的命令及其输出文件的时间戳。构建时对比输出文件的 mtime 是否变化，判断是否重跑；也用于并行调度。</li><li><strong><code>.ninja_deps</code></strong>：记录各输出文件由哪些输入依赖而来（主要是 <code>depfile</code> 解析出的头文件依赖），让 ninja 知道某个头文件变化会影响哪些 <code>.o</code>。</li></ul><p>增量判断流程大致为：某目标的输出文件不存在 → 重建；输出时间戳早于任一输入 → 重建；否则跳过。依赖文件（<code>.ninja_deps</code>）中的头文件被当作输入参与同样的时间戳比较。因此<strong>时间戳的正确性</strong>至关重要——用 <code>touch</code> 故意刷新 mtime 或跨机器同步时时间不一致，都会干扰增量判断。</p><p>手动查看这两个文件可辅助排错：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">tail</span> .ninja_log
<span class="token comment"># 内容示例：起始时间 结束时间 mtime 输出 命令行hash</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>平时无需手动维护它们；若怀疑增量异常，删除这两个文件（连同 build.ninja）重新 CMake 生成即可复位。</p>`,116),c=[d];function t(l,o){return a(),e("div",null,c)}const u=n(i,[["render",t],["__file","ninja.html.vue"]]);export{u as default};
